package PracticePakage;

public class Swapping3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a =500;
		int b=600;

		System.out.println("Old vlaue of a is " +a);
		System.out.println("Old vlaue of b is " +b);
		

		System.out.println("========================");
		
		a=a+b;
		b=a-b;
		a=a-b;

		System.out.println("New vlaue of a is " +a);
		System.out.println("New vlaue of b is " +b);
		

	}

}
